  <script>
    const menuToggle = document.getElementById('menuToggle');
    const mobileNav = document.getElementById('mobileNav');
    menuToggle.addEventListener('click', () => {
      const open = mobileNav.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', open);
    });

    const modal = document.getElementById('donateModal');
    const openDonateBtns = [
      document.getElementById('heroDonate'),
      document.getElementById('headerDonate'),
      document.getElementById('bottomDonate')
    ];
    const closeModalBtn = document.getElementById('closeModal');

    const openModal = () => modal.classList.add('active');
    const closeModal = () => modal.classList.remove('active');

    openDonateBtns.forEach(btn => btn.addEventListener('click', openModal));
    closeModalBtn.addEventListener('click', closeModal);
    modal.addEventListener('click', (event) => {
      if (event.target === modal) closeModal();
    });

    const amountButtons = document.querySelectorAll('.amount-btn');
    const customAmount = document.getElementById('customAmount');
    amountButtons.forEach(button => {
      button.addEventListener('click', () => {
        amountButtons.forEach(b => b.classList.remove('active'));
        button.classList.add('active');
        customAmount.style.display = button.dataset.amount === 'custom' ? 'block' : 'none';
      });
    });
    customAmount.style.display = 'none';

    const accordionItems = document.querySelectorAll('.accordion-item');
    accordionItems.forEach(item => {
      const button = item.querySelector('.accordion-btn');
      button.addEventListener('click', () => {
        const isActive = item.classList.contains('active');
        accordionItems.forEach(i => {
          i.classList.remove('active');
          i.querySelector('.accordion-btn').setAttribute('aria-expanded', 'false');
        });
        if (!isActive) {
          item.classList.add('active');
          button.setAttribute('aria-expanded', 'true');
        }
      });
    });

    const track = document.getElementById('newsTrack');
    const prev = document.getElementById('prevNews');
    const next = document.getElementById('nextNews');
    const slides = document.querySelectorAll('.news-card');
    let currentIndex = 0;

    const renderCarousel = () => {
      track.style.transform = `translateX(-${currentIndex * 100}%)`;
    };

    prev.addEventListener('click', () => {
      currentIndex = (currentIndex - 1 + slides.length) % slides.length;
      renderCarousel();
    });

    next.addEventListener('click', () => {
      currentIndex = (currentIndex + 1) % slides.length;
      renderCarousel();
    });

    const statEls = document.querySelectorAll('.stat-value');
    const statsObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        const el = entry.target;
        const target = Number(el.dataset.target);
        const prefix = el.dataset.prefix || '';
        const suffix = el.dataset.suffix || '';
        let n = 0;
        const duration = 1200;
        const stepTime = 22;
        const steps = duration / stepTime;
        const increment = target / steps;

        const timer = setInterval(() => {
          n += increment;
          if (n >= target) {
            n = target;
            clearInterval(timer);
          }
          el.textContent = `${prefix}${Math.round(n)}${suffix}`;
        }, stepTime);

        observer.unobserve(el);
      });
    }, { threshold: 0.5 });

    statEls.forEach(el => statsObserver.observe(el));
  </script>
